// 使用原S2真实占领写口，验证税源暂停的同tick前后边界与只读钱粮不变。
#define main original_occupation_resource_examples
#include "../test_siege_world_resources.cpp"
#undef main
#include "resident/domains/politics/takeover/politics_occupation_taxpayer.hpp"
#include "resident/storage/common_codec.hpp"
namespace {
struct NoResponsibilities final:PoliticalTakeoverOriginalRead {
 Outcome<std::vector<PoliticalResponsibilityRef>> responsibility_keys(const MilitaryOccupationFact&)const override{return {true,{}, {}};}
 Outcome<PoliticalOriginalResponsibility> original_responsibility(const MilitaryOccupationFact&,const PoliticalResponsibilityRef&)const override{return {false,{},common_failure("NotUsed").error};}
};
int count=0;void check(bool yes,const char* name){++count;if(!yes){std::cerr<<name<<'\n';std::exit(1);}}
}
int main(){Fixture f;f.initial.identity.world_id[0]=1;CommonStore c(f.initial,f.common);auto first=c.next_id("occupation_fiscal_period_suspended");check(first.ok,"first pause ID");check(c.append_fact({first.value,"occupation_fiscal_period_suspended","local_economy"}).ok,"first real boundary");auto occupation=c.next_id("military");check(occupation.ok,"occupation ID");check(c.append_fact({occupation.value,"military_occupation","military"}).ok,"military header");f.state.occupation_facts.front().id=occupation.value;f.access.fact_exists=[&](const StableId& id){return c.state().facts.find(id)!=nullptr;};check(apply_military_occupation(c,f.state,f.catalog,f.access,occupation.value).ok,"actual apply");
 OrganizationCatalog oc;OrganizationRecord old;old.id="old";oc.organizations.insert(old.id,old);OrganizationState org;PoliticsCatalog pc;PoliticalTakeoverCatalog tc;PoliticalTakeoverState ts;NoResponsibilities original;PoliticalTakeoverContext ctx{c,*f.common,org,oc,pc,tc,ts,f.state,f.catalog,f.access,original};PoliticalOccupationFiscalTaxpayerAccess read(ctx);Owner payer{Owner::Kind::organization,"old"};
 auto second=c.next_id("occupation_fiscal_period_suspended");check(second.ok&&c.append_fact({second.value,"occupation_fiscal_period_suspended","local_economy"}).ok,"second pause boundary");auto before=encode_common_state(c.state());
 auto current=read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",10,{});check(current.ok&&current.value.wallet.owner.id=="new"&&current.value.inventory.owner.id=="new"&&current.value.wallet.occupation_fact_ids==std::vector<StableId>{occupation.value},"current proves actual capture");
 auto early=read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",10,first.value);check(early.ok&&early.value.wallet.owner.id=="old"&&early.value.inventory.occupation_fact_ids.empty(),"same tick later capture cannot rewrite earlier pause");auto late=read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",10,second.value);check(late.ok&&late.value.wallet.owner.id=="new"&&late.value.inventory.occupation_fact_ids.size()==1,"same tick prior capture bound");check(!read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",9,{}).ok,"unbound historical time denied");check(!read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",11,{}).ok,"unbound future denied");check(!read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",10,occupation.value).ok,"wrong fact kind boundary denied");check(!read.occupation_fiscal_taxpayer_source({Owner::Kind::organization,"new"},"public-wallet","public-store",10,{}).ok,"cannot replace original payer");check(compare_boundary(before,encode_common_state(c.state())).exact(),"read keeps exact common");auto saved=f.state.occupation_facts.front().asset_manifest->wallets.front().second.from_owner;f.state.occupation_facts.front().asset_manifest->wallets.front().second.from_owner.id="new";check(!read.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",10,{}).ok,"forged manifest denied");f.state.occupation_facts.front().asset_manifest->wallets.front().second.from_owner=saved;
 DynamicStepInput phase{10,11,{},{},{}};ctx.phase=&phase;f.state.occupation_facts.front().tick=11;f.state.sieges.front().result->tick=11;PoliticalOccupationFiscalTaxpayerAccess phased(ctx);check(phased.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",11,{}).ok,"real phase current to next accepted");phase.to_tick=12;check(!phased.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",12,{}).ok,"phase leap denied");phase.to_tick=11;for(const auto* kind:{"occupation_fiscal_source_assessed","occupation_fiscal_payment"}){auto id=c.next_id(kind);check(id.ok&&c.append_fact({id.value,kind,"local_economy"}).ok,"real named fiscal boundary");check(phased.occupation_fiscal_taxpayer_source(payer,"public-wallet","public-store",11,id.value).ok,"assessment/payment named history boundary");}
 check(c.wallet("public-wallet")->balance==200&&c.inventory("public-store")->lots[0].quantity==5&&c.inventory("public-store")->lots[1].quantity==3,"money and goods unchanged");std::cout<<count<<" checks 0 failures\n";
}
